-- PostgreSQL port of the legacy H2 schema (src/main/resources/schema.sql).
-- Same table and column names (unquoted, so existing SQL that uses upper-case
-- identifiers keeps working) and the same types, so the existing DAOs produce
-- identical business results. H2-only constructs are replaced:
--   DECIMAL(p,s)          -> numeric(p,s)
--   INT                   -> integer
--   TIMESTAMP             -> timestamp (without time zone, as in H2)
--   BIGINT AUTO_INCREMENT -> bigint GENERATED BY DEFAULT AS IDENTITY
-- Runs only against the global writer region: DDL is not write-forwarded
-- (PLAT-04). Objects live in the service-owned schema set by Flyway
-- (spring.flyway.schemas=loan_svc / flyway.schemas=loan_svc).

CREATE TABLE cust_acct (
    cust_id       varchar(20) PRIMARY KEY,
    first_nm      varchar(60),
    last_nm       varchar(60),
    ssn_last4     varchar(4),
    emp_nm        varchar(120),
    emp_status    varchar(20),
    annual_income numeric(14,2),
    monthly_debt  numeric(14,2),
    email_addr    varchar(120),
    phone_nbr     varchar(20),
    create_ts     timestamp
);

CREATE TABLE ln_appl (
    appl_id       varchar(30) PRIMARY KEY,
    cust_id       varchar(20),
    prod_cd       varchar(20),
    req_amt       numeric(14,2),
    term_mos      integer,
    purpose_cd    varchar(40),
    collat_val    numeric(14,2),
    collat_type   varchar(40),
    fico_scr      integer,
    ltv_pct       numeric(8,4),
    dti_pct       numeric(8,4),
    base_rate     numeric(8,4),
    final_rate    numeric(8,4),
    elig_cd       varchar(10),
    decision_cd   varchar(10),
    status_cd     varchar(20),
    create_ts     timestamp,
    update_ts     timestamp
);

CREATE TABLE audit_evt (
    evt_id        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    appl_id       varchar(30),
    evt_type      varchar(40),
    evt_msg       varchar(500),
    evt_ts        timestamp
);

CREATE TABLE doc_chklist (
    doc_id        bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    appl_id       varchar(30),
    doc_type      varchar(40),
    req_flg       char(1),
    rcvd_flg      char(1)
);

CREATE TABLE rate_tbl (
    prod_cd       varchar(20) PRIMARY KEY,
    base_rate     numeric(8,4),
    min_fico      integer,
    max_ltv       numeric(8,4)
);
